import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('start sends Assign to each worker; refused twice', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned' });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  assert.equal((await h.start()).ok, false);
});

test('happy path completes', async () => {
  const h = await createHost();
  await h.start();
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('failure waits for both reports', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  assert.equal((await h.run()).status, 'cancelling');
  assert.equal((await h.cancel()).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('abort racing a completion is ignored and completion counts', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

// Random interleavings: check the brief's conclusion.
test('random interleavings keep the run behind its workers', async () => {
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    const reported: Record<number, string[]> = { 0: [], 1: [] };
    for (let s = 0; s < 14; s++) {
      const msgs = await h.inFlight();
      const c = rnd(6);
      if (c === 0) await h.start();
      else if (c === 1) await h.cancel();
      else if (c === 2) await h.workDone(rnd(2) ? 'worker0' : 'worker1');
      else if (c === 3) await h.workFailed(rnd(2) ? 'worker0' : 'worker1');
      else if (msgs.length) {
        const m = msgs[rnd(msgs.length)];
        if (m.action === 'Report') reported[m.data.task as number].push(m.data.outcome as string);
        await h.deliver(m.id);
      }
      const r = await h.run();
      if (r.status === 'completed') assert.ok(reported[0].includes('completed') && reported[1].includes('completed'));
      if (r.status === 'failed' || r.status === 'cancelled') assert.ok(reported[0].length && reported[1].length);
      assert.ok(reported[0].length <= 1 && reported[1].length <= 1);
    }
  }
});

