const D = (msg: string) => S('DELIVER', { msg });

await scenario('happy', [S('START'), D('assign0'), D('assign1'), S('WORK_DONE', { w: 0 }), D('report0'), S('WORK_DONE', { w: 1 }), D('report1'), D('report1'), S('START')]);
await scenario('fail', [S('START'), D('assign1'), D('assign0'), S('WORK_FAILED', { w: 1 }), D('report1'), S('WORK_DONE', { w: 0 }), D('report0'), S('CANCEL')]);
