await scenario('cancel-race', [S('START'), D('assign0'), D('assign1'), S('CANCEL'), S('WORK_DONE', { w: 0 }), D('abort0'), D('report0'), D('abort1'), D('report1')]);
await scenario('abort-before-assign', [S('START'), S('CANCEL'), D('abort0'), D('assign0'), D('abort1'), D('assign1'), S('WORK_FAILED', { w: 0 }), S('WORK_DONE', { w: 1 }), D('report1'), D('report0')]);
for (let i = 0; i < 40; i++) {
  const steps: Step[] = [S('START')];
  for (let k = 0; k < 14; k++) steps.push(ALL[rnd(ALL.length)]);
