      else if (c === 2) await h.workDone(rnd(2) ? 'worker0' : 'worker1');
      else if (c === 3) await h.workFailed(rnd(2) ? 'worker0' : 'worker1');
      else if (msgs.length) {
        const m = msgs[rnd(msgs.length)];
        if (m.action === 'Report') reported[m.data.task as number].push(m.data.outcome as string);
        await h.deliver(m.id);
      }
      const r = await h.run();
      if (r.status === 'completed') assert.ok(reported[0].includes('completed') && reported[1].includes('completed'));
      if (r.status === 'failed' || r.status === 'cancelled') {
        assert.ok((reported[0].length || timedOut[0]) && (reported[1].length || timedOut[1]));
