// Rules the brief requires, as invariants over the spec's state.
const reported = (t) => t === 'completed' || t === 'failed' || t === 'cancelled';
const terminal = (s) => s === 'completed' || s === 'failed' || s === 'cancelled';

export const stateInvariants = [
  { name: 'completed-only-if-both-completed',
    pred: (s) => s.run !== 'completed' || (s.task0 === 'completed' && s.task1 === 'completed') },
  { name: 'ends-only-when-both-reported',
    pred: (s) => !terminal(s.run) || (reported(s.task0) && reported(s.task1)) },
  { name: 'failed-only-if-a-task-failed',
