// Rules the brief requires, as invariants over the spec's state.
const reported = (t) => t === 'completed' || t === 'failed' || t === 'cancelled';
const terminal = (s) => s === 'completed' || s === 'failed' || s === 'cancelled';

export const stateInvariants = [
  { name: 'completed-only-if-both-completed',
    pred: (s) => s.run !== 'completed' || (s.task0 === 'completed' && s.task1 === 'completed') },
  { name: 'ends-only-when-both-reported',
    pred: (s) => !terminal(s.run) || (reported(s.task0) && reported(s.task1)) },
  { name: 'failed-only-if-a-task-failed',
    pred: (s) => s.run !== 'failed' || s.task0 === 'failed' || s.task1 === 'failed' },
  { name: 'cancelled-only-if-none-failed-and-not-both-completed',
    pred: (s) => s.run !== 'cancelled' || (s.task0 !== 'failed' && s.task1 !== 'failed' && !(s.task0 === 'completed' && s.task1 === 'completed')) },
  { name: 'both-reported-means-ended',
    pred: (s) => !(reported(s.task0) && reported(s.task1)) || terminal(s.run) },
  { name: 'task-cancelled-only-after-cancel',
    pred: (s) => (s.task0 !== 'cancelled' && s.task1 !== 'cancelled') || s.run !== 'running' },
  // Change 2: a timeout's Abort can reach an idle worker before its Assign (ignored),
  // so a worker may end up busy on a task that already timed out (failed).
  { name: 'busy-worker-means-task-assigned-or-timed-out',
    pred: (s) => (s.w0 !== 'busy' || s.task0 === 'assigned' || s.task0 === 'failed')
      && (s.w1 !== 'busy' || s.task1 === 'assigned' || s.task1 === 'failed') },
  { name: 'idle-run-has-idle-tasks',
    pred: (s) => s.run !== 'idle' || (s.task0 === 'idle' && s.task1 === 'idle' && s.w0 === 'idle' && s.w1 === 'idle' && !s.retried0 && !s.retried1) },
  // At most one Abort from cancel plus one from a timeout.
  { name: 'bounded-messages-in-flight',
    pred: (s) => s.assign0 <= 1 && s.assign1 <= 1 && s.abort0 <= 2 && s.abort1 <= 2 && s.rep0 !== 'dup' && s.rep1 !== 'dup' },
];

export const transitionInvariants = [
  { name: 'cancel-aborts-only-assigned-tasks',
    pred: (pre, a, d, post) => a !== 'CANCEL'
      || ((post.abort0 === pre.abort0 || pre.task0 === 'assigned') && (post.abort1 === pre.abort1 || pre.task1 === 'assigned')) },
  { name: 'terminal-run-is-final',
    pred: (pre, a, d, post) => !terminal(pre.run) || (post.run === pre.run && post.task0 === pre.task0 && post.task1 === pre.task1) },
  { name: 'reported-task-status-is-final',
    pred: (pre, a, d, post) => (!reported(pre.task0) || post.task0 === pre.task0) && (!reported(pre.task1) || post.task1 === pre.task1) },
  // Change 1: retry a failed task once.
  { name: 'first-failure-while-running-is-retried',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER' || (d.msg !== 'report0' && d.msg !== 'report1')) return true;
      const w = d.msg.slice(-1);
      if (pre['rep' + w] !== 'failed' || pre.run !== 'running' || pre['retried' + w] || pre['task' + w] !== 'assigned') return true;
      return post['task' + w] === 'assigned' && post['retried' + w] === true
        && post['assign' + w] === pre['assign' + w] + 1 && post.run === pre.run;
    } },
  { name: 'repeat-or-cancelling-failure-is-recorded',
    pred: (pre, a, d, post) => {
      if (a !== 'DELIVER' || (d.msg !== 'report0' && d.msg !== 'report1')) return true;
      const w = d.msg.slice(-1);
      if (pre['rep' + w] !== 'failed' || pre['task' + w] !== 'assigned') return true;
      const recordable = (pre.run === 'running' && pre['retried' + w]) || pre.run === 'cancelling';
      return !recordable || (post['task' + w] === 'failed' && post['retried' + w] === pre['retried' + w]);
    } },
  { name: 'retried-never-reverts',
    pred: (pre, a, d, post) => (!pre.retried0 || post.retried0) && (!pre.retried1 || post.retried1) },
  { name: 'retry-only-on-failed-report',
    pred: (pre, a, d, post) => (pre.retried0 === post.retried0 || (a === 'DELIVER' && d.msg === 'report0' && pre.rep0 === 'failed'))
      && (pre.retried1 === post.retried1 || (a === 'DELIVER' && d.msg === 'report1' && pre.rep1 === 'failed')) },
];

export default { stateInvariants, transitionInvariants };

// Capture real traces from src/host.impl.ts through its public interface,
// abstracted to the contract's observable state. One NDJSON file per scenario.
// Run: node spec/capture.ts
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

type Obs = Record<string, string | number | boolean>;

async function observe(h: Host): Promise<Obs> {
  const r = await h.run();
  const msgs = await h.inFlight();
  const count = (to: string, action: string) => msgs.filter((m) => m.to === to && m.action === action).length;
  const rep = (task: number) => {
    const rs = msgs.filter((m) => m.action === 'Report' && m.data.task === task);
    return rs.length === 0 ? 'none' : rs.length > 1 ? 'dup' : String(rs[0].data.outcome);
  };
  return {
    run: r.status, task0: r.task0, task1: r.task1,
    w0: (await h.worker('worker0'))!.status, w1: (await h.worker('worker1'))!.status,
    assign0: count('worker0', 'Assign'), assign1: count('worker1', 'Assign'),
    abort0: count('worker0', 'Abort'), abort1: count('worker1', 'Abort'),
    rep0: rep(0), rep1: rep(1),
    retried0: r.retried0, retried1: r.retried1,
  };
}

const msgName = (m: Message) =>
  m.action === 'Report' ? `report${m.data.task}` : `${m.action.toLowerCase()}${m.to.slice(-1)}`;

type Step = { action: string; data: Record<string, unknown> };

async function apply(h: Host, s: Step): Promise<void> {
  if (s.action === 'START') await h.start();
  else if (s.action === 'CANCEL') await h.cancel();
  else if (s.action === 'WORK_DONE') await h.workDone(`worker${s.data.w}`);
  else if (s.action === 'WORK_FAILED') await h.workFailed(`worker${s.data.w}`);
  else if (s.action === 'DELIVER') {
    const m = (await h.inFlight()).find((x) => msgName(x) === s.data.msg);
    if (m) await h.deliver(m.id);
  }
}

