// Random interleavings: check the brief's conclusion.
test('random interleavings keep the run behind its workers', async () => {
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    const reported: Record<number, string[]> = { 0: [], 1: [] };
    const timedOut = [false, false];
    for (let s = 0; s < 14; s++) {
      const msgs = await h.inFlight();
      const c = rnd(7);
      if (c === 0) await h.start();
      else if (c === 6) {
        const t = rnd(2);
        const before = await h.run();
        const o = await h.taskTimeout(t);
        const after = await h.run();
        if (o.ok) {
          timedOut[t] = true;
          assert.equal(after[t === 0 ? 'task0' : 'task1'], 'failed');
          assert.equal(after[t === 0 ? 'retried0' : 'retried1'], before[t === 0 ? 'retried0' : 'retried1']);
        } else assert.deepEqual(after, before);
      }
      else if (c === 1) await h.cancel();
      else if (c === 2) await h.workDone(rnd(2) ? 'worker0' : 'worker1', 1 + rnd(2));
      else if (c === 3) await h.workFailed(rnd(2) ? 'worker0' : 'worker1');
      else if (msgs.length) {
        const m = msgs[rnd(msgs.length)];
        if (m.action === 'Report') reported[m.data.task as number].push(m.data.outcome as string);

