import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('fresh system is idle', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false, processed: 0 });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('start sends Assign to each worker; refused twice', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: false, processed: 0 });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}],
    ['run', 'worker1', 'Assign', {}],
  ]);
  assert.equal((await h.start()).ok, false);
});

test('happy path completes', async () => {
  const h = await createHost();
  await h.start();
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 1), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual([m.from, m.to, m.action, m.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 1 }]);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false, processed: 2 });
});

test('failure waits for both reports', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  // first failure: retried, still assigned, worker busy again
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false, processed: 0 });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: true, retried1: false, processed: 0 });
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
});

test('retry sends Assign once, then success completes', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  const [rep] = await h.inFlight();
  await h.deliver(rep.id);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  await h.workDone('worker1', 1);
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true, processed: 2 });
});

test('failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false, processed: 0 });
});

test('cancel during retry aborts the retried task', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker0');
  await h.deliverAll();
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', retried0: true, retried1: false, processed: 0 });
});

test('cancel aborts only assigned tasks', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workDone('worker0', 1);
  await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  assert.equal((await h.run()).status, 'cancelling');
  assert.equal((await h.cancel()).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled', retried0: false, retried1: false, processed: 1 });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('abort racing a completion is ignored and completion counts', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.cancel();
  await h.workDone('worker0', 1);
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false, processed: 2 });
});

test('timeout fails the task without retry, aborts the worker, ignores the late report', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false, processed: 0 });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.workDone('worker0', 1); // races the Abort; its report is ignored
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal((await h.run()).task0, 'failed');
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false, processed: 1 });
});

test('timeout while cancelling ends the run; refused when idle, ended or bad task', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.deliverAll();
  await h.workDone('worker1', 1);
