});

test('timeout during a retry is final', async () => {
  const h = await createHost();
  await h.start();
  await h.deliverAll();
  await h.workFailed('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'failed', retried0: false, retried1: true, processed: 0 });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

// Random interleavings: check the brief's conclusion.
test('random interleavings keep the run behind its workers', async () => {
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  for (let i = 0; i < 2000; i++) {
    const h = await createHost();
    const reported: Record<number, string[]> = { 0: [], 1: [] };
    const timedOut = [false, false];
    for (let s = 0; s < 14; s++) {
      const msgs = await h.inFlight();
      const c = rnd(7);
      if (c === 0) await h.start();
      else if (c === 6) {
        const t = rnd(2);
        const before = await h.run();
        const o = await h.taskTimeout(t);
        const after = await h.run();
        if (o.ok) {
          timedOut[t] = true;
          assert.equal(after[t === 0 ? 'task0' : 'task1'], 'failed');
          assert.equal(after[t === 0 ? 'retried0' : 'retried1'], before[t === 0 ? 'retried0' : 'retried1']);
        } else assert.deepEqual(after, before);
      }
      else if (c === 1) await h.cancel();
      else if (c === 2) await h.workDone(rnd(2) ? 'worker0' : 'worker1', 1 + rnd(2));
      else if (c === 3) await h.workFailed(rnd(2) ? 'worker0' : 'worker1');
      else if (msgs.length) {
        const m = msgs[rnd(msgs.length)];
        if (m.action === 'Report') {
          reported[m.data.task as number].push(m.data.outcome as string);
          assert.equal(m.data.items, m.data.outcome === 'completed' ? m.data.items : 0);
          const pre = await h.run();
          const tk = m.data.task === 0 ? 'task0' : 'task1';
          const recorded = (pre.status === 'running' || pre.status === 'cancelling') && pre[tk] === 'assigned'
            && m.data.outcome === 'completed';
          await h.deliver(m.id);
          const post = await h.run();
          assert.equal(post.processed, pre.processed + (recorded ? (m.data.items as number) : 0));
          if (recorded) assert.equal(post[tk], 'completed');
        } else await h.deliver(m.id);
      }
      const r = await h.run();
      if (r.status === 'completed') assert.ok(reported[0].includes('completed') && reported[1].includes('completed'));
      if (r.status === 'failed' || r.status === 'cancelled') {
        assert.ok((reported[0].length || timedOut[0]) && (reported[1].length || timedOut[1]));
      }
      for (const t of [0, 1]) {
        const rs = reported[t];
        const retried = t === 0 ? r.retried0 : r.retried1;
        assert.ok(rs.length <= 3);
        // a second report only after a first failure that was retried
        if (rs.length === 2) assert.ok(rs[0] === 'failed' && retried);
        if (retried) assert.ok(rs[0] === 'failed');
      }
      if (r.status === 'failed') assert.ok(r.task0 === 'failed' || r.task1 === 'failed');
    }
  }
});

