// SAM v2 strict-profile spec of the stateful core of src/: the run (src/run.ts),
// the two workers (src/worker.ts), and the network (src/host.impl.ts).
// The network is abstracted to per-message-kind counts: Assign/Abort to each
// worker, and the outcome of the Report in flight from each worker
// ('none' when none; 'dup' if a second report were sent while one is in flight).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = {
  run: 'idle', task0: 'idle', task1: 'idle',
  w0: 'idle', w1: 'idle',
  assign0: 0, assign1: 0, abort0: 0, abort1: 0,
  rep0: 'none', rep1: 'none',
  retried0: false, retried1: false,
};

const KEYS = Object.keys(INITIAL_STATE);
const MSGS = ['assign0', 'assign1', 'abort0', 'abort1', 'report0', 'report1'];

const reported = (t) => t === 'completed' || t === 'failed' || t === 'cancelled';
const settle = (status, t0, t1) => {
  if (t0 === 'completed' && t1 === 'completed') return 'completed';
  if (!(reported(t0) && reported(t1))) return status;
  if (t0 === 'failed' || t1 === 'failed') return 'failed';
  return 'cancelled';
};
const others = (...written) => KEYS.filter((k) => !written.includes(k));
const sendReport = (model, w, outcome) => (model['rep' + w] === 'none' ? outcome : 'dup');

const finish = (outcome) => (model) => (proposal, { reject, next, unchanged }) => {
  const w = proposal.w;
  if (model['w' + w] !== 'busy') return reject('worker-not-busy');
  next['w' + w] = 'idle';
  next['rep' + w] = sendReport(model, w, outcome);
  unchanged(...others('w' + w, 'rep' + w));
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      run: { type: 'string' }, task0: { type: 'string' }, task1: { type: 'string' },
      w0: { type: 'string' }, w1: { type: 'string' },
      assign0: { type: 'number' }, assign1: { type: 'number' },
      abort0: { type: 'number' }, abort1: { type: 'number' },
      rep0: { type: 'string' }, rep1: { type: 'string' },
      retried0: { type: 'boolean' }, retried1: { type: 'boolean' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      TIMEOUT: { action: (data = {}) => ({ ...data }), schema: { t: 'number' }, domain: [{ t: 0 }, { t: 1 }, { t: 2 }] },
      WORK_DONE: { action: (data = {}) => ({ ...data }), schema: { w: 'number' }, domain: [{ w: 0 }, { w: 1 }] },
      WORK_FAILED: { action: (data = {}) => ({ ...data }), schema: { w: 'number' }, domain: [{ w: 0 }, { w: 1 }] },
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { msg: 'string' }, domain: MSGS.map((msg) => ({ msg })) },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.run !== 'idle') return reject('run-already-started');
        next.run = 'running';
        next.task0 = 'assigned';
        next.task1 = 'assigned';
        next.assign0 = model.assign0 + 1;
        next.assign1 = model.assign1 + 1;
        unchanged(...others('run', 'task0', 'task1', 'assign0', 'assign1'));
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.run !== 'running') return reject('run-not-running');
        next.run = 'cancelling';
        next.abort0 = model.task0 === 'assigned' ? model.abort0 + 1 : model.abort0;
        next.abort1 = model.task1 === 'assigned' ? model.abort1 + 1 : model.abort1;
        unchanged(...others('run', 'abort0', 'abort1'));
      },
      TIMEOUT: (model) => (proposal, { reject, next, unchanged }) => {
        const t = proposal.t;
        if (t !== 0 && t !== 1) return reject('unknown-task');
        if (model.run !== 'running' && model.run !== 'cancelling') return reject('run-not-active');
        if (model['task' + t] !== 'assigned') return reject('task-not-assigned');
        const t0 = t === 0 ? 'failed' : model.task0;
        const t1 = t === 1 ? 'failed' : model.task1;
        next.task0 = t0;
        next.task1 = t1;
        next.run = settle(model.run, t0, t1);
        next['abort' + t] = model['abort' + t] + 1;
        unchanged(...others('task0', 'task1', 'run', 'abort' + t));
      },
      WORK_DONE: finish('completed'),
      WORK_FAILED: finish('failed'),
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const msg = proposal.msg;
        if (msg === 'assign0' || msg === 'assign1') {
          const w = msg.slice(-1);
          if (model[msg] === 0) return reject('not-in-flight');
          next[msg] = model[msg] - 1;
          next['w' + w] = 'busy';
          unchanged(...others(msg, 'w' + w));
          return;
        }
        if (msg === 'abort0' || msg === 'abort1') {
          const w = msg.slice(-1);
          if (model[msg] === 0) return reject('not-in-flight');
          next[msg] = model[msg] - 1;
          if (model['w' + w] === 'busy') {
            next['w' + w] = 'idle';
            next['rep' + w] = sendReport(model, w, 'cancelled');
            unchanged(...others(msg, 'w' + w, 'rep' + w));
          } else {
            unchanged(...others(msg));
          }
          return;
        }
        if (msg === 'report0' || msg === 'report1') {
          const w = msg.slice(-1);
          const outcome = model['rep' + w];
          if (outcome === 'none') return reject('not-in-flight');
          next['rep' + w] = 'none';
          if (model['task' + w] !== 'assigned') {
            // late report for a task no longer assigned (timed out): ignored
            unchanged(...others('rep' + w));
          } else if (outcome === 'failed' && model.run === 'running' && !model['retried' + w]) {
            // first failure while running: retry once, the task stays assigned
            next['retried' + w] = true;
            next['assign' + w] = model['assign' + w] + 1;
            unchanged(...others('rep' + w, 'retried' + w, 'assign' + w));
          } else if (model.run === 'running' || model.run === 'cancelling') {
            const t0 = w === '0' ? outcome : model.task0;
            const t1 = w === '1' ? outcome : model.task1;
            next.task0 = t0;
            next.task1 = t1;
            next.run = settle(model.run, t0, t1);
            unchanged(...others('rep' + w, 'task0', 'task1', 'run'));
          } else {
            unchanged(...others('rep' + w));
          }
          return;
        }
        return reject('unknown-message');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  WORK_DONE: (data = {}) => intents.WORK_DONE(data),
  WORK_FAILED: (data = {}) => intents.WORK_FAILED(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

