  const rep = (task: number) => {
    const rs = msgs.filter((m) => m.action === 'Report' && m.data.task === task);
    return rs.length === 0 ? 'none' : rs.length > 1 ? 'dup' : String(rs[0].data.outcome);
  };
  const items = (task: number) => {
    const rs = msgs.filter((m) => m.action === 'Report' && m.data.task === task);
    return rs.length === 1 ? (rs[0].data.items as number) : 0;
  };
  return {
    run: r.status, task0: r.task0, task1: r.task1,
    w0: (await h.worker('worker0'))!.status, w1: (await h.worker('worker1'))!.status,
    assign0: count('worker0', 'Assign'), assign1: count('worker1', 'Assign'),
    abort0: count('worker0', 'Abort'), abort1: count('worker1', 'Abort'),
    rep0: rep(0), rep1: rep(1),
    retried0: r.retried0, retried1: r.retried1,
    items0: items(0), items1: items(1), processed: r.processed,
  };
}

const msgName = (m: Message) =>
  m.action === 'Report' ? `report${m.data.task}` : `${m.action.toLowerCase()}${m.to.slice(-1)}`;

type Step = { action: string; data: Record<string, unknown> };

async function apply(h: Host, s: Step): Promise<void> {
  if (s.action === 'START') await h.start();
  else if (s.action === 'CANCEL') await h.cancel();
  else if (s.action === 'TIMEOUT') await h.taskTimeout(s.data.t as number);
  else if (s.action === 'WORK_DONE') await h.workDone(`worker${s.data.w}`, s.data.items as number);
  else if (s.action === 'WORK_FAILED') await h.workFailed(`worker${s.data.w}`);
  else if (s.action === 'DELIVER') {
    const m = (await h.inFlight()).find((x) => msgName(x) === s.data.msg);
    if (m) await h.deliver(m.id);
  }
}

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

const ALL: Step[] = [
  { action: 'START', data: {} }, { action: 'CANCEL', data: {} },
  { action: 'TIMEOUT', data: { t: 0 } }, { action: 'TIMEOUT', data: { t: 1 } }, { action: 'TIMEOUT', data: { t: 2 } },
  ...[0, 1].flatMap((w) => [0, 1, 2, 3, 1, 2].map((items) => ({ action: 'WORK_DONE', data: { w, items } }))),
  { action: 'WORK_FAILED', data: { w: 0 } }, { action: 'WORK_FAILED', data: { w: 1 } },
  ...['assign0', 'assign1', 'abort0', 'abort1', 'report0', 'report1'].map((msg) => ({ action: 'DELIVER', data: { msg } })),
];

let seed = 7;
const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };

async function scenario(name: string, steps: Step[]) {
  const h = await createHost();
  const lines: string[] = [];
  for (const s of steps) {
    const pre = await observe(h);
    await apply(h, s);
    const post = await observe(h);
    lines.push(JSON.stringify({ pre, action: s.action, data: s.data, post }));
  }
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}

const S = (a: string, data: Record<string, unknown> = {}): Step => ({ action: a, data });
const D = (msg: string) => S('DELIVER', { msg });

await scenario('happy', [S('START'), D('assign0'), D('assign1'), S('WORK_DONE', { w: 0, items: 2 }), D('report0'), S('WORK_DONE', { w: 1, items: 1 }), D('report1'), D('report1'), S('START')]);
await scenario('fail', [S('START'), D('assign1'), D('assign0'), S('WORK_FAILED', { w: 1 }), D('report1'), S('WORK_DONE', { w: 0, items: 2 }), D('report0'), S('CANCEL')]);
await scenario('cancel', [S('START'), D('assign0'), D('assign1'), S('WORK_DONE', { w: 0, items: 2 }), D('report0'), S('CANCEL'), S('CANCEL'), D('abort1'), D('report1')]);
await scenario('cancel-race', [S('START'), D('assign0'), D('assign1'), S('CANCEL'), S('WORK_DONE', { w: 0, items: 2 }), D('abort0'), D('report0'), D('abort1'), D('report1')]);
await scenario('abort-before-assign', [S('START'), S('CANCEL'), D('abort0'), D('assign0'), D('abort1'), D('assign1'), S('WORK_FAILED', { w: 0 }), S('WORK_DONE', { w: 1, items: 1 }), D('report1'), D('report0')]);
await scenario('retry-then-fail', [S('START'), D('assign0'), D('assign1'), S('WORK_FAILED', { w: 0 }), D('report0'), D('assign0'), S('WORK_FAILED', { w: 0 }), D('report0'), S('WORK_FAILED', { w: 1 }), D('report1'), D('assign1'), S('WORK_DONE', { w: 1, items: 1 }), D('report1')]);
await scenario('retry-then-cancel', [S('START'), D('assign0'), D('assign1'), S('WORK_FAILED', { w: 1 }), D('report1'), S('CANCEL'), D('assign1'), D('abort1'), D('abort0'), D('report0'), D('report1')]);
await scenario('fail-while-cancelling', [S('START'), D('assign0'), D('assign1'), S('WORK_FAILED', { w: 0 }), S('CANCEL'), D('report0'), D('abort0'), D('abort1'), D('report1')]);
await scenario('timeout-late-report', [S('START'), D('assign0'), D('assign1'), S('TIMEOUT', { t: 0 }), S('WORK_DONE', { w: 0, items: 2 }), D('abort0'), D('report0'), S('TIMEOUT', { t: 0 }), S('WORK_DONE', { w: 1, items: 1 }), D('report1'), S('TIMEOUT', { t: 1 })]);
await scenario('timeout-aborts-busy', [S('START'), D('assign0'), D('assign1'), S('TIMEOUT', { t: 1 }), D('abort1'), D('report1'), S('WORK_FAILED', { w: 0 }), D('report0'), D('assign0'), S('TIMEOUT', { t: 0 }), D('abort0'), D('report0')]);
await scenario('cancel-then-timeout', [S('START'), D('assign0'), D('assign1'), S('CANCEL'), S('TIMEOUT', { t: 0 }), D('abort0'), D('report0'), D('abort0'), D('abort1'), D('report1')]);
await scenario('timeout-before-assign', [S('START'), S('TIMEOUT', { t: 0 }), D('abort0'), D('assign0'), S('WORK_DONE', { w: 0, items: 2 }), D('report0'), S('TIMEOUT', { t: 2 })]);
for (let i = 0; i < 80; i++) {
  const steps: Step[] = [S('START')];
  for (let k = 0; k < 14; k++) steps.push(ALL[rnd(ALL.length)]);
  await scenario(`random${i}`, steps);
}

